<!DOCTYPE html>
<html lang="ro">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <meta name="robots" content="noindex, nofollow">
  <meta name="theme-color" content="#061a15">
  <title>Ajutor și suport — Nordvale</title>
  <meta name="description" content="Centrul de ajutor Nordvale pentru bilete, rezervări, plăți și vizite.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap" rel="stylesheet">
  <style>
    :root{
      --pine-950:#061a15;--pine-900:#09251d;--pine-850:#0d3027;--pine-800:#123b30;--pine-700:#1b5242;
      --acid:#dffc62;--ember:#f27b4a;--sky:#8dd8ca;--cream:#fffdf6;--oat:#f0ecdf;--moss:#b7c9a3;
      --ink:#16231e;--muted:rgba(22,35,30,.6);--line:rgba(9,37,29,.12);
      --shadow:0 30px 90px -54px rgba(6,26,21,.7);--card-shadow:0 20px 58px -40px rgba(6,26,21,.52)
    }
    *{box-sizing:border-box}html{background:var(--oat);scroll-behavior:smooth}body{margin:0;overflow-x:hidden;background:var(--oat);color:var(--ink);font-family:"DM Sans",sans-serif;text-rendering:optimizeLegibility}button,input,select,textarea{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}[hidden]{display:none!important}::selection{background:var(--acid);color:var(--pine-950)}
    .shell{width:min(1460px,calc(100% - 32px));margin-inline:auto}.topo{background-image:radial-gradient(circle at 15% 12%,rgba(223,252,98,.15),transparent 21%),radial-gradient(circle at 89% 18%,rgba(242,123,74,.13),transparent 18%),url("data:image/svg+xml,%3Csvg width='760' height='760' viewBox='0 0 760 760' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' stroke='%23fff' stroke-opacity='.055' stroke-width='1.05'%3E%3Cpath d='M74 206c43-106 166-167 278-119 89 39 107 147 52 218-51 66-143 59-194 124-58 73-49 188-142 228-91 38-186-37-164-132 20-89 111-106 122-190 8-57-5-88 48-129Z'/%3E%3Cpath d='M112 231c34-81 128-126 214-90 69 29 82 113 41 167-39 50-110 45-150 95-44 55-38 144-109 174-70 29-143-29-126-102 15-68 85-81 94-146 6-43-4-67 36-98Z'/%3E%3Cpath d='M493 410c57-79 161-89 227-18 60 64 24 169-55 198-71 26-142-17-201 28-52 40-62 123-129 129-74 6-126-73-84-135 38-56 112-39 155-92 35-43 39-79 87-110Z'/%3E%3C/g%3E%3C/svg%3E");background-size:auto,auto,760px 760px}
    .site-header{position:sticky;top:0;z-index:70;padding:12px 0;background:linear-gradient(180deg,rgba(240,236,223,.97),rgba(240,236,223,.82),transparent)}.nav{display:flex;align-items:center;gap:16px;padding:10px 12px 10px 16px;border:1px solid rgba(255,255,255,.12);border-radius:22px;background:rgba(6,26,21,.9);box-shadow:0 24px 70px -46px rgba(0,0,0,.9);backdrop-filter:blur(22px) saturate(130%);color:#fff}.brand{display:flex;align-items:center;gap:11px;min-width:0}.brand-mark{display:grid;place-items:center;width:42px;height:42px;flex:0 0 auto;border:1px solid rgba(223,252,98,.42);border-radius:15px;background:rgba(223,252,98,.08);color:var(--acid)}.brand-copy{min-width:0;line-height:1}.brand-copy strong{display:block;font-family:"Fraunces",serif;font-size:18px;font-weight:600;letter-spacing:-.02em}.brand-copy span{display:block;margin-top:5px;color:rgba(255,255,255,.5);font-size:10px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap}.main-nav{display:flex;align-items:center;gap:6px;margin-left:auto}.main-nav a{padding:10px 12px;border-radius:12px;color:rgba(255,255,255,.68);font-size:13px;font-weight:600}.main-nav a:hover{background:rgba(255,255,255,.07);color:#fff}.nav-actions{display:flex;align-items:center;gap:8px}.ticket-cta{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:13px;background:var(--acid);color:var(--pine-950);font-size:13px;font-weight:800;white-space:nowrap}.menu-btn{display:none;place-items:center;width:40px;height:40px;border:0;border-radius:13px;background:rgba(255,255,255,.07);color:#fff}
    .layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:24px;padding:18px 0 104px}.sidebar{position:sticky;top:92px;align-self:start;padding:18px;border:1px solid var(--line);border-radius:26px;background:rgba(255,253,246,.82);box-shadow:var(--card-shadow);backdrop-filter:blur(18px)}.profile-mini{display:flex;align-items:center;gap:12px;padding:8px 8px 20px;border-bottom:1px solid var(--line)}.avatar{position:relative;display:grid;place-items:center;width:50px;height:50px;flex:0 0 auto;border-radius:18px;background:var(--pine-900);color:var(--acid);font-family:"Fraunces",serif;font-size:18px;font-weight:700}.avatar:after{content:"";position:absolute;right:-2px;bottom:-2px;width:13px;height:13px;border:3px solid var(--cream);border-radius:50%;background:#54c97a}.profile-mini strong{display:block;font-size:14px}.profile-mini span span{display:block;margin-top:4px;color:rgba(22,35,30,.54);font-size:11px}.side-nav{display:grid;gap:6px;padding:16px 0}.side-nav a{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:14px;color:rgba(22,35,30,.64);font-size:13px;font-weight:650;transition:.2s ease}.side-nav a:hover{background:rgba(9,37,29,.06);color:var(--pine-900)}.side-nav a.active{background:var(--pine-900);color:#fff}.side-nav svg{width:18px;height:18px;flex:0 0 auto}.side-status{padding:15px;border-radius:18px;background:var(--oat)}.status-line{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:800}.status-dot{width:8px;height:8px;border-radius:50%;background:#54c97a;box-shadow:0 0 0 6px rgba(84,201,122,.12)}.side-status p{margin:8px 0 0;color:rgba(22,35,30,.56);font-size:11px;line-height:1.5}
    .content{min-width:0}.hero{position:relative;overflow:hidden;display:grid;grid-template-columns:minmax(0,1fr) 410px;min-height:380px;border-radius:36px;background:var(--pine-900);color:#fff;box-shadow:var(--shadow)}.hero:after{content:"";position:absolute;inset:auto -90px -170px auto;width:430px;height:430px;border:1px solid rgba(223,252,98,.1);border-radius:50%;box-shadow:0 0 0 48px rgba(223,252,98,.035),0 0 0 96px rgba(223,252,98,.02)}.hero-copy{position:relative;z-index:3;display:flex;flex-direction:column;justify-content:center;padding:44px}.eyebrow{display:inline-flex;align-items:center;gap:8px;width:max-content;padding:7px 10px;border:1px solid rgba(223,252,98,.22);border-radius:999px;background:rgba(223,252,98,.08);color:var(--acid);font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 0 7px rgba(223,252,98,.1)}.hero h1{max-width:790px;margin:20px 0 12px;font-family:"Fraunces",serif;font-size:clamp(42px,4.8vw,70px);font-weight:600;letter-spacing:-.058em;line-height:.96}.hero h1 em{color:var(--acid);font-style:italic}.hero-copy>p{max-width:670px;margin:0;color:rgba(255,255,255,.66);font-size:15px;line-height:1.7}.search-wrap{position:relative;margin-top:26px;max-width:690px}.support-search{width:100%;height:58px;padding:0 128px 0 50px;border:1px solid rgba(255,255,255,.16);border-radius:18px;background:rgba(255,255,255,.09);color:#fff;outline:none;backdrop-filter:blur(18px);transition:.2s ease}.support-search::placeholder{color:rgba(255,255,255,.48)}.support-search:focus{border-color:rgba(223,252,98,.58);box-shadow:0 0 0 4px rgba(223,252,98,.08)}.search-icon{position:absolute;left:18px;top:50%;width:20px;height:20px;transform:translateY(-50%);color:var(--acid)}.search-btn{position:absolute;right:7px;top:7px;height:44px;padding:0 17px;border:0;border-radius:13px;background:var(--acid);color:var(--pine-950);font-size:12px;font-weight:900}.search-suggestions{position:absolute;z-index:30;top:66px;left:0;right:0;overflow:hidden;border:1px solid rgba(255,255,255,.12);border-radius:18px;background:rgba(6,26,21,.97);box-shadow:0 30px 80px -35px rgba(0,0,0,.9);backdrop-filter:blur(20px)}.search-suggestions button{display:flex;align-items:center;gap:12px;width:100%;padding:13px 16px;border:0;border-bottom:1px solid rgba(255,255,255,.07);background:transparent;color:#fff;text-align:left}.search-suggestions button:last-child{border-bottom:0}.search-suggestions button:hover{background:rgba(255,255,255,.06)}.search-suggestions strong{display:block;font-size:12px}.search-suggestions span{display:block;margin-top:3px;color:rgba(255,255,255,.48);font-size:10px}.hero-visual{position:relative;display:grid;place-items:center;min-height:380px;padding:32px}.hero-visual:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--pine-900),rgba(9,37,29,.22) 42%,rgba(9,37,29,.08)),url("https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1100&q=84") center/cover;opacity:.74}.support-console{position:relative;z-index:3;width:min(320px,100%);padding:24px;border:1px solid rgba(255,255,255,.17);border-radius:30px;background:linear-gradient(145deg,rgba(255,255,255,.15),rgba(255,255,255,.045));box-shadow:0 34px 80px -36px rgba(0,0,0,.8);backdrop-filter:blur(22px);transform:rotate(2deg)}.console-head{display:flex;align-items:center;justify-content:space-between}.console-head span{font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;color:var(--acid)}.console-live{display:flex;align-items:center;gap:7px;color:rgba(255,255,255,.62);font-size:10px}.console-live i{width:7px;height:7px;border-radius:50%;background:#54c97a;box-shadow:0 0 0 6px rgba(84,201,122,.1)}.support-agent{display:flex;align-items:center;gap:12px;margin:22px 0;padding:15px;border-radius:19px;background:rgba(6,26,21,.46)}.agent-avatar{display:grid;place-items:center;width:46px;height:46px;border-radius:16px;background:var(--acid);color:var(--pine-950);font-family:"Fraunces",serif;font-weight:700}.support-agent strong{display:block;font-size:13px}.support-agent span{display:block;margin-top:4px;color:rgba(255,255,255,.52);font-size:10px}.console-stat{display:grid;grid-template-columns:1fr 1fr;gap:10px}.console-stat div{padding:14px;border-radius:16px;background:rgba(255,255,255,.07)}.console-stat strong{display:block;color:var(--acid);font-family:"Fraunces",serif;font-size:23px}.console-stat span{display:block;margin-top:4px;color:rgba(255,255,255,.48);font-size:9px;text-transform:uppercase;letter-spacing:.08em}.console-note{margin:16px 0 0;color:rgba(255,255,255,.56);font-size:10px;line-height:1.55}
    .summary-strip{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0}.summary-card{display:flex;align-items:center;gap:13px;padding:16px;border:1px solid var(--line);border-radius:20px;background:var(--cream);box-shadow:var(--card-shadow)}.summary-icon{display:grid;place-items:center;width:42px;height:42px;flex:0 0 auto;border-radius:14px;background:var(--pine-900);color:var(--acid)}.summary-icon svg{width:20px;height:20px}.summary-card strong{display:block;font-size:12px}.summary-card span{display:block;margin-top:4px;color:var(--muted);font-size:10px}
    .content-grid{display:grid;grid-template-columns:minmax(0,1.28fr) minmax(300px,.72fr);gap:16px}.stack{display:grid;gap:16px}.card{padding:24px;border:1px solid var(--line);border-radius:28px;background:var(--cream);box-shadow:var(--card-shadow)}.card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:20px}.card-kicker{margin:0 0 7px;color:var(--pine-700);font-size:9px;font-weight:900;letter-spacing:.16em;text-transform:uppercase}.card h2,.card h3{margin:0;font-family:"Fraunces",serif;font-weight:600;letter-spacing:-.03em}.card h2{font-size:27px}.card h3{font-size:21px}.card-head p{max-width:620px;margin:7px 0 0;color:var(--muted);font-size:12px;line-height:1.6}.text-link{border:0;background:transparent;color:var(--pine-700);font-size:11px;font-weight:900;white-space:nowrap}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:0 17px;border:1px solid transparent;border-radius:14px;font-size:12px;font-weight:850}.btn-primary{background:var(--acid);color:var(--pine-950)}.btn-dark{background:var(--pine-900);color:#fff}.btn-ghost{border-color:var(--line);background:var(--cream);color:var(--pine-900)}
    .visit-context{display:grid;grid-template-columns:120px minmax(0,1fr) auto;gap:16px;align-items:center;padding:17px;border:1px solid rgba(242,123,74,.2);border-radius:22px;background:linear-gradient(135deg,rgba(242,123,74,.09),rgba(223,252,98,.08))}.visit-thumb{height:90px;border-radius:17px;background:linear-gradient(180deg,transparent,rgba(6,26,21,.42)),url("https://images.unsplash.com/photo-1500534314209-a25ddb2bd4297?auto=format&fit=crop&w=500&q=80") center/cover}.visit-copy small{display:block;color:var(--ember);font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.visit-copy h3{margin:6px 0 5px;font-size:20px}.visit-copy p{margin:0;color:var(--muted);font-size:11px}.visit-actions{display:grid;gap:8px;justify-items:end}
    .category-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.category-card{position:relative;overflow:hidden;min-height:156px;padding:19px;border:1px solid var(--line);border-radius:22px;background:var(--oat);transition:.22s ease;text-align:left}.category-card:hover{transform:translateY(-3px);border-color:rgba(9,37,29,.22);box-shadow:var(--card-shadow)}.category-card:after{content:"";position:absolute;right:-18px;bottom:-26px;width:96px;height:96px;border-radius:50%;background:var(--acid);opacity:.11}.category-card svg{width:24px;height:24px;color:var(--pine-700)}.category-card strong{display:block;margin-top:22px;font-family:"Fraunces",serif;font-size:20px;font-weight:600}.category-card span{display:block;margin-top:6px;color:var(--muted);font-size:10px;line-height:1.5}.category-card b{position:absolute;right:16px;top:16px;display:grid;place-items:center;min-width:26px;height:26px;padding:0 7px;border-radius:999px;background:var(--cream);color:var(--pine-700);font-size:9px}
    .articles{display:grid;gap:8px}.article-row{display:grid;grid-template-columns:42px minmax(0,1fr) auto;gap:12px;align-items:center;padding:13px;border-radius:17px;transition:.18s ease}.article-row:hover{background:var(--oat)}.article-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:14px;background:rgba(9,37,29,.07);color:var(--pine-700)}.article-icon svg{width:19px;height:19px}.article-row strong{display:block;font-size:12px}.article-row span{display:block;margin-top:4px;color:var(--muted);font-size:10px}.article-row>svg{width:17px;height:17px;color:rgba(22,35,30,.36)}
    .ticket-list{display:grid;gap:10px}.ticket{padding:16px;border:1px solid var(--line);border-radius:20px;background:var(--cream)}.ticket-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.ticket-ref{color:var(--pine-700);font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.ticket h4{margin:6px 0 4px;font-family:"Fraunces",serif;font-size:18px;font-weight:600}.ticket p{margin:0;color:var(--muted);font-size:10px;line-height:1.5}.ticket-status{display:inline-flex;align-items:center;gap:6px;padding:6px 9px;border-radius:999px;font-size:9px;font-weight:900;white-space:nowrap}.ticket-status.open{background:rgba(242,123,74,.12);color:#a94c27}.ticket-status.waiting{background:rgba(141,216,202,.18);color:#236c61}.ticket-status.closed{background:rgba(84,201,122,.13);color:#267443}.ticket-meta{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:13px;padding-top:12px;border-top:1px solid var(--line)}.ticket-meta span{color:var(--muted);font-size:9px}.ticket-meta button{border:0;background:transparent;color:var(--pine-700);font-size:10px;font-weight:900}
    .channel-grid{display:grid;gap:10px}.channel{display:flex;align-items:center;gap:13px;padding:15px;border:1px solid var(--line);border-radius:19px;background:var(--cream);transition:.18s ease}.channel:hover{transform:translateY(-2px);box-shadow:var(--card-shadow)}.channel-icon{display:grid;place-items:center;width:44px;height:44px;flex:0 0 auto;border-radius:15px;background:var(--pine-900);color:var(--acid)}.channel-icon svg{width:20px;height:20px}.channel-copy{min-width:0}.channel-copy strong{display:block;font-size:12px}.channel-copy span{display:block;margin-top:4px;color:var(--muted);font-size:9px}.channel-action{margin-left:auto;color:var(--pine-700);font-size:10px;font-weight:900;white-space:nowrap}.availability{display:flex;align-items:center;gap:8px;margin-top:10px;padding:10px;border-radius:13px;background:var(--oat);font-size:9px;color:var(--muted)}.availability i{width:7px;height:7px;border-radius:50%;background:#54c97a}
    .status-board{display:grid;gap:9px}.status-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:10px 0;border-bottom:1px solid var(--line)}.status-row:last-child{border-bottom:0}.status-row strong{font-size:11px}.status-row span{display:inline-flex;align-items:center;gap:6px;color:#267443;font-size:9px;font-weight:900}.status-row span:before{content:"";width:7px;height:7px;border-radius:50%;background:#54c97a}
    .faq-list{display:grid;gap:8px}.faq-item{overflow:hidden;border:1px solid var(--line);border-radius:18px;background:var(--cream)}.faq-question{display:flex;align-items:center;justify-content:space-between;gap:14px;width:100%;padding:15px 17px;border:0;background:transparent;text-align:left}.faq-question strong{font-size:12px}.faq-question svg{width:18px;height:18px;transition:.2s ease}.faq-item.open .faq-question svg{transform:rotate(45deg)}.faq-answer{max-height:0;overflow:hidden;transition:max-height .28s ease}.faq-answer p{margin:0;padding:0 17px 16px;color:var(--muted);font-size:11px;line-height:1.65}
    .mobile-nav{display:none}.mobile-menu{position:fixed;z-index:100;inset:0;display:flex;flex-direction:column;padding:16px;background:rgba(6,26,21,.98);color:#fff;transform:translateX(100%);transition:.28s ease;visibility:hidden}.mobile-menu.open{transform:translateX(0);visibility:visible}.mobile-menu-head{display:flex;align-items:center;justify-content:space-between}.mobile-menu-links{display:grid;gap:7px;margin-top:36px}.mobile-menu-links a{padding:15px;border-bottom:1px solid rgba(255,255,255,.09);font-family:"Fraunces",serif;font-size:25px}.toast{position:fixed;z-index:140;right:20px;bottom:20px;max-width:min(360px,calc(100% - 40px));padding:14px 17px;border-radius:15px;background:var(--pine-900);color:#fff;box-shadow:0 24px 70px -30px rgba(0,0,0,.8);font-size:11px;font-weight:750;opacity:0;transform:translateY(18px);pointer-events:none;transition:.24s ease}.toast.show{opacity:1;transform:translateY(0)}
    .overlay{position:fixed;z-index:110;inset:0;display:grid;place-items:center;padding:18px;background:rgba(6,26,21,.72);backdrop-filter:blur(10px);opacity:0;visibility:hidden;transition:.2s ease}.overlay.open{opacity:1;visibility:visible}.dialog{width:min(760px,100%);max-height:min(820px,calc(100vh - 36px));overflow:auto;border-radius:30px;background:var(--cream);box-shadow:0 35px 110px -36px rgba(0,0,0,.9)}.dialog-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:23px 24px;border-bottom:1px solid var(--line)}.dialog-head h2{margin:0;font-family:"Fraunces",serif;font-size:28px}.dialog-head p{margin:6px 0 0;color:var(--muted);font-size:11px}.icon-btn{display:grid;place-items:center;width:40px;height:40px;flex:0 0 auto;border:0;border-radius:13px;background:var(--oat);color:var(--pine-900)}.dialog-body{padding:22px 24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.field{display:grid;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:10px;font-weight:850}.control{width:100%;min-height:48px;padding:0 13px;border:1px solid var(--line);border-radius:14px;background:#fff;color:var(--ink);outline:none}.control:focus{border-color:rgba(9,37,29,.35);box-shadow:0 0 0 4px rgba(9,37,29,.05)}textarea.control{min-height:120px;padding-top:13px;resize:vertical}.topic-options{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.topic-option{padding:13px;border:1px solid var(--line);border-radius:16px;background:var(--cream);text-align:left}.topic-option.active{border-color:var(--pine-700);background:rgba(9,37,29,.055)}.topic-option strong{display:block;font-size:10px}.topic-option span{display:block;margin-top:4px;color:var(--muted);font-size:9px}.dialog-actions{display:flex;justify-content:flex-end;gap:9px;padding:18px 24px;border-top:1px solid var(--line)}
    @media(max-width:1180px){.main-nav{display:none}.menu-btn{display:grid}.hero{grid-template-columns:minmax(0,1fr) 350px}.content-grid{grid-template-columns:1fr}.aside-stack{grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}.summary-strip{grid-template-columns:repeat(2,1fr)}}
