(()=>{'use strict';
 const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)],body=document.body,toast=$('#toast');
 const showToast=m=>{toast.textContent=m;toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove('show'),2600)};
 const menu=$('#mobileMenu'); $('#menuOpen')?.addEventListener('click',()=>{menu.classList.add('open');menu.setAttribute('aria-hidden','false');body.style.overflow='hidden'}); $('#menuClose')?.addEventListener('click',()=>{menu.classList.remove('open');menu.setAttribute('aria-hidden','true');body.style.overflow=''});
 const articleData=[
  {cat:'bilete',title:'QR-ul nu se încarcă la intrare',desc:'Pași rapizi pentru acces offline și Wallet.',icon:'ticket'},
  {cat:'rezervari',title:'Cum schimb data unei rezervări?',desc:'Eligibilitate, intervale și eventuale diferențe de preț.',icon:'calendar'},
  {cat:'plati',title:'Descarcă sau corectează factura',desc:'Unde găsești factura și cum schimbi datele fiscale.',icon:'doc'},
  {cat:'vizita',title:'Ce se întâmplă în caz de ploaie?',desc:'Reguli meteo, suspendări și opțiuni automate.',icon:'cloud'},
  {cat:'bilete',title:'Transferă biletul altui participant',desc:'Schimbarea beneficiarului înainte de check-in.',icon:'user'},
  {cat:'vizita',title:'Echipamentul recomandat pe trasee',desc:'Încălțăminte, haine și obiecte de evitat.',icon:'mountain'}
 ];
 const iconSvg={ticket:'<path d="M4 7h16v4a2 2 0 0 0 0 4v4H4v-4a2 2 0 0 0 0-4z"/>',calendar:'<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 3v4M16 3v4M4 10h16"/>',doc:'<path d="M6 3h9l3 3v15H6z"/><path d="M9 11h6M9 15h6"/>',cloud:'<path d="M6 18h11a4 4 0 0 0 0-8 6 6 0 0 0-11.5 1.5A3.5 3.5 0 0 0 6 18Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',mountain:'<path d="m4 17 5-10 3 6 2-4 6 8"/><path d="M3 20h18"/>'};
 const renderArticles=(cat='all')=>{const items=cat==='all'?articleData.slice(0,5):articleData.filter(x=>x.cat===cat);$('#articlesList').innerHTML=items.map(a=>`<button class="article-row" type="button" data-article="${a.title}"><span class="article-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8">${iconSvg[a.icon]}</svg></span><span><strong>${a.title}</strong><span>${a.desc}</span></span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m9 5 7 7-7 7"/></svg></button>`).join('');$$('[data-article]').forEach(b=>b.addEventListener('click',()=>showToast(`Deschidere articol: ${b.dataset.article}`)))};renderArticles();
 $$('[data-category]').forEach(btn=>btn.addEventListener('click',()=>{renderArticles(btn.dataset.category);$('#articlesCard').scrollIntoView({behavior:'smooth',block:'start'});showToast(`Ghiduri filtrate: ${btn.querySelector('strong').textContent}`)})); $('#allArticles')?.addEventListener('click',()=>{renderArticles();showToast('Sunt afișate cele mai utile articole din toate categoriile.')});
 const suggestions=['Schimbarea datei rezervării','Factura comenzii','QR-ul nu se încarcă','Politica pentru vreme','Transferul unui bilet','Rambursarea unei comenzi']; const search=$('#supportSearch'),box=$('#searchSuggestions');
 const updateSuggestions=()=>{const q=search.value.trim().toLowerCase();if(!q){box.hidden=true;return}const hits=suggestions.filter(x=>x.toLowerCase().includes(q)).slice(0,5);box.innerHTML=hits.length?hits.map(x=>`<button type="button" data-suggestion="${x}"><span><strong>${x}</strong><span>Vezi ghidul recomandat</span></span></button>`).join(''):'<button type="button"><span><strong>Niciun ghid exact</strong><span>Creează o solicitare și te ajutăm direct.</span></span></button>';box.hidden=false;$$('[data-suggestion]',box).forEach(b=>b.addEventListener('click',()=>{search.value=b.dataset.suggestion;box.hidden=true;showToast(`Căutare: ${b.dataset.suggestion}`)}))}; search?.addEventListener('input',updateSuggestions); search?.addEventListener('keydown',e=>{if(e.key==='Enter'){$('#searchBtn').click()}}); $('#searchBtn')?.addEventListener('click',()=>{const q=search.value.trim();if(!q){showToast('Scrie mai întâi ce cauți.');search.focus();return}box.hidden=true;showToast(`Căutăm răspunsuri pentru „${q}”.`)}); document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))box.hidden=true});
 $$('.faq-question').forEach(q=>q.addEventListener('click',()=>{const item=q.closest('.faq-item'),ans=$('.faq-answer',item),open=item.classList.toggle('open');ans.style.maxHeight=open?ans.scrollHeight+'px':'0px'}));
 const overlay=$('#ticketOverlay'); const openTicket=()=>{overlay.classList.add('open');overlay.setAttribute('aria-hidden','false');body.style.overflow='hidden'}; const closeTicket=()=>{overlay.classList.remove('open');overlay.setAttribute('aria-hidden','true');body.style.overflow=''}; $('#newTicket')?.addEventListener('click',openTicket);$('#newTicketTop')?.addEventListener('click',openTicket);$('#visitHelp')?.addEventListener('click',()=>{openTicket();$('#supportSubject').value='Ajutor pentru vizita din 18 august'});$('#ticketClose')?.addEventListener('click',closeTicket);$('#ticketCancel')?.addEventListener('click',closeTicket);overlay?.addEventListener('click',e=>{if(e.target===overlay)closeTicket()});
 $$('[data-topic]').forEach(b=>b.addEventListener('click',()=>{$$('[data-topic]').forEach(x=>x.classList.remove('active'));b.classList.add('active')})); $('#ticketSubmit')?.addEventListener('click',()=>{const subject=$('#supportSubject').value.trim(),message=$('#supportMessage').value.trim();if(subject.length<4||message.length<10){showToast('Completează titlul și câteva detalii despre situație.');return}closeTicket();showToast('Solicitarea #SUP-4894 a fost trimisă.')});
 $('#startChat')?.addEventListener('click',()=>showToast('Chat demonstrativ pornit. Mara se conectează...')); $('#viewVisit')?.addEventListener('click',()=>location.href='/cont/bilete'); $$('[data-open-ticket]').forEach(b=>b.addEventListener('click',()=>showToast(`Deschidere solicitare #${b.dataset.openTicket}`)));
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeTicket();$('#menuClose')?.click()}});
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches){$$('.hero-copy > *').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:560,delay:50+i*65,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'}));$('.support-console')?.animate([{opacity:0,transform:'translate(28px,22px) rotate(8deg) scale(.94)'},{opacity:1,transform:'translate(0,0) rotate(2deg) scale(1)'}],{duration:820,delay:180,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:430,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});o.unobserve(e.target)}}),{threshold:.07});$$('.card,.summary-card').forEach(el=>o.observe(el))}
})();
</script>
<script>
(function(){
  function nvAuth(){ try { return JSON.parse(localStorage.getItem('nordvale_auth')||'null'); } catch(e){ return null; } }
  var a = nvAuth();
  if(!a || !a.token){ location.href='/autentificare?next='+encodeURIComponent(location.pathname+location.search); return; }
  var AH = { 'Authorization':'Bearer '+a.token };
  function api(ac,opt){ opt=opt||{}; opt.headers=Object.assign({},AH,opt.headers||{}); return fetch('/api/proxy.php?action='+ac,opt).then(function(r){return r.json().catch(function(){return{};});}).catch(function(){return{};}); }
  function post(ac,b){ return api(ac,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}); }
  function esc(s){ var d=document.createElement('div'); d.textContent=(s==null?'':String(s)); return d.innerHTML; }
  function initials(n){ n=(n||'').trim(); if(!n)return 'N'; var p=n.split(/\s+/); return (((p[0]||'')[0]||'')+((p[1]||'')[0]||'')).toUpperCase()||'N'; }
  function fmtDate(iso){ if(!iso)return ''; var d=new Date(iso); if(isNaN(d))return ''; return d.toLocaleDateString('ro-RO',{day:'2-digit',month:'short',year:'numeric'}); }
  function hydrateUser(u){ if(!u)return; var name=u.name||(((u.first_name||'')+' '+(u.last_name||'')).trim())||'Cont Nordvale'; window.__nvName=name; var box=document.querySelector('.profile-mini'); if(box){ var av=box.querySelector('.avatar'); if(av)av.textContent=initials(name); var st=box.querySelector('strong'); if(st)st.textContent=name; } }
  document.querySelectorAll('a,button').forEach(function(el){ if((el.textContent||'').trim()==='Deconectare'){ el.addEventListener('click',function(ev){ ev.preventDefault(); post('logout').finally(function(){ localStorage.removeItem('nordvale_auth'); location.href='/'; }); }); } });
  hydrateUser(a.user);
  api('me').then(function(d){ if(d&&d.success&&d.data){ a.user=Object.assign({},a.user,d.data); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e){} hydrateUser(a.user); } });

  api('acc-orders').then(function(d){ if(!(d&&d.success&&Array.isArray(d.data))||!d.data.length)return; var sel=document.querySelector('#supportOrder'); if(sel){ sel.innerHTML=d.data.slice(0,8).map(function(o){ return '<option>'+esc(o.order_number+' · '+(o.event||fmtDate(o.created_at)))+'</option>'; }).join('')+'<option>Fără comandă asociată</option>'; } });
  api('acc-tickets').then(function(d){ if(!(d&&d.success&&d.data))return; var up=(d.data.upcoming||[])[0]; if(!up)return; var vc=document.querySelector('.visit-context .visit-copy'); if(vc){ var sm=vc.querySelector('small'); if(sm&&up.code)sm.textContent=up.code; var h3=vc.querySelector('h3'); if(h3&&up.event)h3.textContent=up.event; var p=vc.querySelector('p'); if(p){ p.textContent=[up.date?fmtDate(up.date):'', up.time?String(up.time).slice(0,5):'', up.venue||''].filter(Boolean).join(' · '); } } });
})();
</script>
</body></html>
